.thread_status.newhotfolder {
	background-position: 0 -280px;
}

.thread_status.newhotclosefolder {
	background-position: 0 -300px;
}

.thread_status.newclosefolder {
	background-position: 0 -320px;
}

.modcp_nav_item {
	display: block;
	padding: 1px 0 1px 23px;
	background-image: url(images/modcp_sprite.png);
	background-repeat: no-repeat;
}

.modcp_nav_home {
	background-position: 0 0;
}

.modcp_nav_announcements {
	background-position: 0 -20px;
}

.modcp_nav_reports {
	background-position: 0 -40px;
}

.modcp_nav_modqueue {
	background-position: 0 -60px;
}

.modcp_nav_modlogs {
	background-position: 0 -80px;
}

.modcp_nav_editprofile {
	background-position: 0 -100px;
}

.modcp_nav_banning {
	background-position: 0 -120px;
}

.modcp_nav_warninglogs {
	background-position: 0 -140px;
}

.modcp_nav_ipsearch {
	background-position: 0 -160px;
}

.modqueue_message {
	overflow: auto;
	max-height: 250px;
}

.modqueue_controls {
	width: 270px;
	float: right;
	text-align: center;
	border: 1px solid #ccc;
	background: #fff;
	padding: 6px;
	font-weight: bold;
}

.modqueue_controls label {
	margin-right: 8px;
}

.label_radio_ignore,
.label_radio_delete,
.label_radio_approve {
	font-weight: bold;
}

.modqueue_meta {
	color: #444;
	font-size: 95%;
	margin-bottom: 8px;
}

.modqueue_mass {
	list-style: none;
	margin: 0;
	width: 150px;
	padding: 0;
}

.modqueue_mass li {
	margin-bottom: 4px;
	padding: 0;
}

.modqueue_mass li a {
	display: block;
	padding: 4px;
	border: 1px solid transparent;
}

.modqueue_mass li a:hover {
	background: #efefef;
	border: 1px solid #ccc;
	text-decoration: none;
}

.star_rating,
.star_rating li a:hover,
.star_rating .current_rating {
	background: url(images/star_rating.png) left -1000px repeat-x;
	vertical-align: middle;
}

.star_rating {
	position: relative;
	width:80px;
	height:16px;
	overflow: hidden;
	list-style: none;
	margin: 0;
	padding: 0;
	background-position: left top;
}

td .star_rating {
	margin: auto;
}

.star_rating li {
	display: inline;
}

.star_rating li a,
.star_rating .current_rating {
	position: absolute;
	text-indent: -1000px;
	height: 16px;
	line-height: 16px;
	outline: none;
	overflow: hidden;
	border: none;
	top:0;
	left:0;
}

.star_rating_notrated li a:hover {
	background-position: left bottom;
}

.star_rating li a.one_star {
	width:20%;
	z-index:6;
}

.star_rating li a.two_stars {
	width:40%;
	z-index:5;
}

.star_rating li a.three_stars {
	width:60%;
	z-index:4;
}

.star_rating li a.four_stars {
	width:80%;
	z-index:3;
}

.star_rating li a.five_stars {
	width:100%;
	z-index:2;
}

.star_rating .current_rating {
	z-index:1;
	background-position: left center;
}

.star_rating_success,
.success_message {
	color: #00b200;
	font-weight: bold;
	font-size: 10px;
	margin-bottom: 10px;
}

.inline_rating {
	background: url(images/star_rating.png) left -1000px repeat-x;
	float: left;
	vertical-align: middle;
	padding-right: 5px;
}

ul.thread_tools,
ul.thread_tools li {
	list-style: none;
	padding: 0;
	margin: 0;
}

ul.thread_tools li {
	padding-left: 24px;
	padding-bottom: 4px;
	margin-bottom: 3px;
	font-size: 11px;
	background-image: url(images/showthread_sprite.png);
	background-repeat: no-repeat;
}

ul.thread_tools li.printable {
	background-position: 0 0;
}

ul.thread_tools li.sendthread {
	background-position: 0 -20px;
}

ul.thread_tools li.subscription_add {
	background-position: 0 -40px;
}

ul.thread_tools li.subscription_remove {
	background-position: 0 -60px;
}

ul.thread_tools li.poll {
	background-position: 0 -80px;
}

.showthread_spinner {
	width: 100%;
	margin: 0 auto;
	display: block;
	text-align: center;
	padding: 20px;
}

a:link,
a:visited,
a:hover,
a:active {
	color: #555;
}

#logo {
	background: #202020 url(images/colors/black_header.png) top left repeat-x;
	border-bottom: 1px solid #000;
}

#header ul.menu li a {
	color: #fff;
}

#panel .upper {
	background: #dcdbdc url(images/colors/black_tcat.png) repeat-x;
	color: #000;
	border-top: 1px solid #fff;
	border-bottom: 1px solid #bbb;
}

#panel .upper a:link,
#panel .upper a:visited,
#panel .upper a:hover,
#panel .upper a:active {
	color: #000;
}

#panel input.textbox {
	border-color: #ccc;
}

#panel input.button {
	background: #202121 url(images/colors/black_thead.png) top left repeat-x;
	color: #fff;
	border-color: #000;
}

.thead {
	background: #202121 url(images/colors/black_thead.png) top left repeat-x;
	border-bottom: 1px solid #000;
}

.tcat {
	background: #dcdbdc url(images/colors/black_tcat.png) repeat-x;
	color: #000000;
	border-top: 1px solid #fff;
	border-bottom: 1px solid #bbb;
}

.tcat a:link,
.tcat a:visited,
.tcat a:hover,
.tcat a:active {
	color: #000000;
}

.thead input.textbox,
.thead select {
	border: 1px solid #111;
}

.popup_menu .popup_item:hover {
	background: #333;
	color: #fff;
}

.tt-suggestion.tt-is-under-cursor {
    background-color: #333;
	color: #fff;
}

.pagination a:hover {
	background-color: #333;
	color: #fff;
	border-color: #000;
}

